time.patch('/timers/:id', async (c) => {
  const user = c.get('user')
  const id = c.req.param('id')
  const [existing] = await db.select().from(clockTimers)
    .where(and(eq(clockTimers.id, id), eq(clockTimers.userId, user.id)))
  if (!existing) return c.json({ error: 'Not found' }, 404)

  const body = await c.req.json().catch(() => ({}))
  const patch: Partial<typeof clockTimers.$inferInsert> = { updatedAt: new Date() }
  const label = str(body.label, 80); if (label) patch.label = label
  const dur = int(body.durationSec, 1, 24 * 3600); if (dur !== null) patch.durationSec = dur
  const tone = str(body.tone, 200); if (tone) patch.tone = tone
  if ('toneName' in body) patch.toneName = str(body.toneName, 120)
  if (typeof body.announce === 'boolean') patch.announce = body.announce
  const so = int(body.sortOrder, 0, 9999); if (so !== null) patch.sortOrder = so

  await db.update(clockTimers).set(patch).where(eq(clockTimers.id, id))
  const [row] = await db.select().from(clockTimers).where(eq(clockTimers.id, id))
  return c.json({ timer: row })
})

time.delete('/timers/:id', async (c) => {
  const user = c.get('user')
  const id = c.req.param('id')
  await db.delete(clockTimers).where(and(eq(clockTimers.id, id), eq(clockTimers.userId, user.id)))
  return c.json({ ok: true })
})

// ─── Running timer countdowns (server-backed, shared with the companion) ─────
time.get('/runs', async (c) => {
  const user = c.get('user')
  const rows = await db.select().from(clockTimerRuns)
    .where(eq(clockTimerRuns.userId, user.id))
    .orderBy(asc(clockTimerRuns.createdAt))
  return c.json({ runs: rows })
})

time.post('/runs', async (c) => {
  const user = c.get('user')
  const body = await c.req.json().catch(() => ({}))
  const durationSec = int(body.durationSec, 1, 24 * 3600)
  if (durationSec === null) return c.json({ error: 'durationSec required' }, 400)

  const now = new Date()
  const id = crypto.randomUUID()
  await db.insert(clockTimerRuns).values({
    id, userId: user.id,
    label: str(body.label, 80) ?? 'Timer',
    tone: str(body.tone, 200) ?? 'builtin:beacon',
    toneName: str(body.toneName, 120),
    announce: bool(body.announce, true),
    durationSec,
    endsAt: Date.now() + durationSec * 1000,
    paused: false,
    remainingMs: durationSec * 1000,
    createdAt: now,
  })
  const [row] = await db.select().from(clockTimerRuns).where(eq(clockTimerRuns.id, id))
  return c.json({ run: row })
})

time.patch('/runs/:id', async (c) => {
  const user = c.get('user')
  const id = c.req.param('id')
  const [existing] = await db.select().from(clockTimerRuns)
    .where(and(eq(clockTimerRuns.id, id), eq(clockTimerRuns.userId, user.id)))
  if (!existing) return c.json({ error: 'Not found' }, 404)

  const body = await c.req.json().catch(() => ({}))
  const patch: Partial<typeof clockTimerRuns.$inferInsert> = {}
  // Pause: freeze remaining. Resume: re-derive endsAt from remaining.
  if (typeof body.paused === 'boolean' && body.paused !== existing.paused) {
    if (body.paused) {
      patch.paused = true
      patch.remainingMs = Math.max(0, existing.endsAt - Date.now())
    } else {
      patch.paused = false
      patch.endsAt = Date.now() + existing.remainingMs
    }
  }
  const label = str(body.label, 80); if (label) patch.label = label
  if (Object.keys(patch).length === 0) return c.json({ run: existing })

  await db.update(clockTimerRuns).set(patch).where(eq(clockTimerRuns.id, id))
  const [row] = await db.select().from(clockTimerRuns).where(eq(clockTimerRuns.id, id))
  return c.json({ run: row })
})

time.delete('/runs/:id', async (c) => {
  const user = c.get('user')
  const id = c.req.param('id')
  await db.delete(clockTimerRuns).where(and(eq(clockTimerRuns.id, id), eq(clockTimerRuns.userId, user.id)))
  return c.json({ ok: true })
})
